        for arm in p['arm_orders'][task]:
            files=sorted((root/PHASE/task).glob(arm+'-a*/attempt-result.json'),key=lambda f:int(f.parent.name.rsplit('a',1)[1]));attempts=[json.loads(f.read_text()) for f in files];native=[a for a in attempts if a['native_started']];last=attempts[-1] if attempts else {};adjudication_path=root/PHASE/task/(arm+'-guard-readjudication.json');adjudication=json.loads(adjudication_path.read_text()) if adjudication_path.exists() else None;totals={k:sum(a.get('stream',{}).get('totals',{}).get(k,0) for a in native) for k in ('uncached_input','cache_creation','cache_read','output')}
            rows.append(dict(task=task,arm=arm,activation_mode='explicit-v2',native_attempts=len(native),attempts_retained=len(attempts),native_wall_seconds=sum(a.get('wall_seconds') or 0 for a in native),provider_models=sorted({m for a in native for m in a.get('stream',{}).get('provider_reported_model_ids',[])}),usage_complete=bool(native) and all(a.get('stream',{}).get('usage_complete',False) for a in native),per_model=[a.get('stream',{}).get('per_model',{}) for a in native],totals=totals,reported_token_volume=sum(totals.values()),cache_adjusted_5m_proxy=sum(totals[k]*w for k,w in zip(totals,(1,1.25,.1,1))),plugins=adjudication['verified_plugins'] if adjudication else last.get('verified_plugins'),guard_readjudication=adjudication,plugin_version_note='builtin independent version absent/null;code bound to CLI2.1.302/frozen binary SHA',configuration_guard_failed=last.get('configuration_guard_failed',False),expansion=last.get('expansion'),grade_valid=last.get('grade_valid',False),solved=last.get('solved'),quota_before=last.get('quota_before'),quota_after=last.get('quota_after'),rate_events=[e for a in native for e in a.get('stream',{}).get('rate_limit_events',[])],owned_actor_absent=last.get('owned_actor_absent'),owned_graders_absent=last.get('owned_graders_absent'),attempt_metadata_sha256=[sha(f) for f in files],context_sha256=last.get('context_sha256'),error=last.get('error')))
